Here's a test file for `business_days_between`. I used `2024-01-01` as an anchor because it's a Monday, so the weekday math is easy to check by eye.

```python
from datetime import date, timedelta

import pytest

from date_utils import business_days_between  # adjust to your module path


# Reference calendar (Jan 2024):
#   Mon 1, Tue 2, Wed 3, Thu 4, Fri 5, Sat 6, Sun 7, Mon 8


class TestBasicBehavior:
    def test_same_day_returns_zero(self):
        d = date(2024, 1, 1)
        assert business_days_between(d, d) == 0

    def test_start_is_inclusive_end_is_exclusive(self):
        # Mon -> Tue counts only Monday
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 2)) == 1

    def test_monday_to_friday_excludes_friday(self):
        # Mon, Tue, Wed, Thu
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 5)) == 4

    def test_monday_to_saturday_includes_friday(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 6)) == 5

    def test_full_week_monday_to_monday(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 8)) == 5

    def test_two_full_weeks(self):
        assert business_days_between(date(2024, 1, 1), date(2024, 1, 15)) == 10


class TestWeekends:
    def test_friday_to_monday_counts_only_friday(self):
        assert business_days_between(date(2024, 1, 5), date(2024, 1, 8)) == 1

    def test_saturday_to_monday_is_zero(self):
        assert business_days_between(date(2024, 1, 6), date(2024, 1, 8)) == 0

    def test_saturday_to_sunday_is_zero(self):
        assert business_days_between(date(2024, 1, 6), date(2024, 1, 7)) == 0

    def test_sunday_to_monday_is_zero(self):
        assert business_days_between(date(2024, 1, 7), date(2024, 1, 8)) == 0

    def test_sunday_to_tuesday_counts_monday(self):
        assert business_days_between(date(2024, 1, 7), date(2024, 1, 9)) == 1


class TestReversedRange:
    def test_start_after_end_returns_zero(self):
        assert business_days_between(date(2024, 1, 8), date(2024, 1, 1)) == 0

    def test_start_one_day_after_end_returns_zero(self):
        assert business_days_between(date(2024, 1, 2), date(2024, 1, 1)) == 0


class TestCalendarBoundaries:
    def test_across_year_boundary(self):
        # Fri 2023-12-29, Sat, Sun, Mon 2024-01-01 -> Fri and Mon count
        assert business_days_between(date(2023, 12, 29), date(2024, 1, 2)) == 2

    def test_across_leap_day(self):
        # Wed 2024-02-28, Thu 2024-02-29 -> 2
        assert business_days_between(date(2024, 2, 28), date(2024, 3, 1)) == 2

    def test_no_leap_day_in_non_leap_year(self):
        # Tue 2023-02-28 -> Wed 2023-03-01 -> 1
        assert business_days_between(date(2023, 2, 28), date(2023, 3, 1)) == 1

    def test_full_leap_year(self):
        # 366 days = 52 weeks + Mon + Tue -> 52*5 + 2
        assert business_days_between(date(2024, 1, 1), date(2025, 1, 1)) == 262

    def test_full_non_leap_year(self):
        # 2023-01-01 is a Sunday; 365 days = 52 weeks + 1 extra Sunday
        assert business_days_between(date(2023, 1, 1), date(2024, 1, 1)) == 260


class TestProperties:
    @pytest.mark.parametrize("offset", range(7))
    def test_any_seven_day_window_has_five_business_days(self, offset):
        start = date(2024, 1, 1) + timedelta(days=offset)
        assert business_days_between(start, start + timedelta(days=7)) == 5

    @pytest.mark.parametrize("weeks", [1, 4, 13, 52])
    def test_whole_weeks_scale_linearly(self, weeks):
        start = date(2024, 1, 3)  # Wednesday; any start works
        end = start + timedelta(weeks=weeks)
        assert business_days_between(start, end) == 5 * weeks

    @pytest.mark.parametrize(
        "a, b, c",
        [
            (date(2024, 1, 1), date(2024, 1, 4), date(2024, 1, 20)),
            (date(2024, 1, 6), date(2024, 1, 7), date(2024, 1, 8)),   # weekend split
            (date(2024, 1, 5), date(2024, 1, 5), date(2024, 1, 12)),  # empty first half
        ],
    )
    def test_additive_over_split_point(self, a, b, c):
        assert business_days_between(a, c) == (
            business_days_between(a, b) + business_days_between(b, c)
        )

    @pytest.mark.parametrize("offset", range(0, 60, 7))
    def test_result_never_exceeds_calendar_days_or_goes_negative(self, offset):
        start = date(2024, 1, 1)
        end = start + timedelta(days=offset)
        result = business_days_between(start, end)
        assert 0 <= result <= offset
